// spacefastPlaintextCredentialError refuses to send a credential (a
// SPACEFAST_TOKEN or a saved page key) over plain http unless the target is
// loopback, so a local test server still works. It mirrors the generated API
// client's plaintextCredentialError, which this separate HTTP client bypasses.
func spacefastPlaintextCredentialError(u *url.URL) error {
	if u == nil || !strings.EqualFold(u.Scheme, "http") {
		return nil
	}
	host := strings.TrimSuffix(strings.TrimSpace(u.Hostname()), ".")
	if strings.EqualFold(host, "localhost") {
		return nil
	}
	if addr, err := netip.ParseAddr(host); err == nil && addr.Unmap().IsLoopback() {
		return nil
	}
	return fmt.Errorf("refusing to send Spacefast credentials over plaintext http to %s; use https", host)
}

func spacefastPublish(api, bearer string, payload map[string]any, files map[string][]byte) (*spacefastReceipt, error) {
	var buf bytes.Buffer
	mw := multipart.NewWriter(&buf)
	meta, err := json.Marshal(payload)
	if err != nil {
		return nil, err
	}
	ph := textproto.MIMEHeader{}
	ph.Set("Content-Disposition", `form-data; name="payload"`)
	ph.Set("Content-Type", "application/json")
	pw, err := mw.CreatePart(ph)
	if err != nil {
		return nil, err
	}
	if _, err := pw.Write(meta); err != nil {
		return nil, err
	}
	names := make([]string, 0, len(files))
	for name := range files {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		h := textproto.MIMEHeader{}
		h.Set("Content-Disposition", fmt.Sprintf(`form-data; name="file"; filename=%q`, name))
		if strings.HasSuffix(name, ".html") {
			h.Set("Content-Type", "text/html; charset=utf-8")
		} else {
			h.Set("Content-Type", "application/json")
		}
		fw, err := mw.CreatePart(h)
		if err != nil {
			return nil, err
		}
		if _, err := fw.Write(files[name]); err != nil {
			return nil, err
		}
	}
	if err := mw.Close(); err != nil {
		return nil, err
	}

	req, err := http.NewRequest(http.MethodPost, api+"/v1/publish", &buf)
	if err != nil {
		return nil, fmt.Errorf("building Spacefast request: %w", err)
	}
	req.Header.Set("Content-Type", mw.FormDataContentType())
	req.Header.Set("Accept", "application/json")
	req.Header.Set("User-Agent", spacefastClientVersion)
	if bearer != "" {
		if err := spacefastPlaintextCredentialError(req.URL); err != nil {
			return nil, err
		}
		req.Header.Set("Authorization", "Bearer "+bearer)
	} else {
		// Anonymous publishes need a caller-held principal to make the
		// idempotency key safe to retry.
		req.Header.Set("Idempotency-Key", spacefastRandomHex(16))
		req.Header.Set("X-Spacefast-Idempotency-Principal", spacefastRandomHex(32))
	}

	httpClient := &http.Client{
		Timeout: 120 * time.Second,
		CheckRedirect: func(*http.Request, []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}
	resp, err := httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("publishing to Spacefast: %w", err)
	}
	defer resp.Body.Close()
	raw, _ := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
	if resp.StatusCode >= 300 {
		var problem struct {
			Title  string `json:"title"`
			Detail string `json:"detail"`
			Code   string `json:"code"`
		}
		_ = json.Unmarshal(raw, &problem)
		msg := spacefastFirstNonEmpty(problem.Detail, problem.Title, strings.TrimSpace(string(raw)))
		msg = spacefastTruncate(msg, 300)
		return nil, fmt.Errorf("Spacefast returned %s: %s", resp.Status, msg)
	}
	var env struct {
		Data spacefastReceipt `json:"data"`
	}
	if err := json.Unmarshal(raw, &env); err != nil {
		return nil, fmt.Errorf("reading Spacefast receipt: %w", err)
	}
	if env.Data.Space.ID == "" {
		return nil, fmt.Errorf("Spacefast receipt had no space id")
	}
	return &env.Data, nil
}

func spacefastRandomHex(n int) string {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		return fmt.Sprintf("%x", time.Now().UnixNano())
	}
	return hex.EncodeToString(b)
}

// spacefastTruncate shortens s to at most max runes, never splitting a
// UTF-8 character.
func spacefastTruncate(s string, max int) string {
	runes := []rune(s)
	if len(runes) <= max {
		return s
	}
	return string(runes[:max]) + "…"
}

func spacefastFirstNonEmpty(vals ...string) string {
	for _, v := range vals {
		if strings.TrimSpace(v) != "" {
			return v
		}
	}
	return ""
}

func spacefastTitle(name string) string {
	words := strings.Split(name, "-")
	for i, w := range words {
		if w != "" {
			words[i] = strings.ToUpper(w[:1]) + w[1:]
		}
	}
	return strings.Join(words, " ")
}

// spacefastDecode parses one JSON value with numbers kept exact
// (json.Number), so large IDs reach the page and data.json unchanged.
func spacefastDecode(raw []byte, v any) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	if err := dec.Decode(v); err != nil {
		return err
	}
	if _, err := dec.Token(); err != io.EOF {
		return fmt.Errorf("unexpected data after JSON value")
	}
	return nil
}

// spacefastDataFile returns the output as JSON when it parses, so the page
// ships a machine-readable copy next to the rendered one.
func spacefastDataFile(body []byte) []byte {
	var v any
	if spacefastDecode(bytes.TrimSpace(body), &v) == nil {
		out, err := json.MarshalIndent(v, "", "  ")
		if err == nil {
			return out
		}
	}
	out, _ := json.Marshal(map[string]string{"output": string(body)})
	return out
}

// spacefastLocateRows finds the record list in a command's JSON output: a
// top-level array of objects, or the first array of objects under a common
// envelope key. It returns that array's raw bytes.
func spacefastLocateRows(raw []byte) ([]byte, bool) {
	raw = bytes.TrimSpace(raw)
	if len(raw) == 0 {
		return nil, false
	}
	switch raw[0] {
	case '[':
		var items []json.RawMessage
		if json.Unmarshal(raw, &items) != nil || len(items) == 0 {
			return nil, false
		}
		for _, item := range items {
			item = bytes.TrimSpace(item)
			if len(item) == 0 || item[0] != '{' {
				return nil, false
			}
		}
		return raw, true
	case '{':
		var obj map[string]json.RawMessage
		if json.Unmarshal(raw, &obj) != nil {
			return nil, false
		}
		for _, key := range []string{"results", "data", "items", "records", "rows", "entries"} {
			if inner, ok := obj[key]; ok {
				if rows, ok := spacefastLocateRows(inner); ok {
					return rows, true
				}
			}
		}
	}
	return nil, false
}

// spacefastRowKeyOrder maps each record field to the position it first
// appears among the records' own top-level keys, so the table keeps the
// command's field order. Keys of nested objects and envelopes don't count.
func spacefastRowKeyOrder(rowsRaw []byte) map[string]int {
	order := map[string]int{}
	var items []json.RawMessage
	if json.Unmarshal(rowsRaw, &items) != nil {
		return order
	}
	for _, item := range items {
		dec := json.NewDecoder(bytes.NewReader(item))
		if tok, err := dec.Token(); err != nil || tok != json.Delim('{') {
			continue
		}
		for dec.More() {
			tok, err := dec.Token()
			if err != nil {
				break
			}
			if key, ok := tok.(string); ok {
				if _, seen := order[key]; !seen {
					order[key] = len(order)
				}
			}
			var skip json.RawMessage
			if err := dec.Decode(&skip); err != nil {
				break
			}
		}
	}
	return order
}

func spacefastCell(v any) string {
	switch x := v.(type) {
	case nil:
		return ""
	case string:
		return x
	case json.Number:
		return x.String()
	case bool:
		if x {
			return "yes"
		}
		return "no"
	default:
		b, _ := json.Marshal(x)
		return string(b)
	}
}

func renderSpacefastPage(name string, body []byte) []byte {
	trimmed := bytes.TrimSpace(body)
	var parsed any
	isJSON := spacefastDecode(trimmed, &parsed) == nil

	var rows []map[string]any
	var order map[string]int
	if isJSON {
		if rowsRaw, ok := spacefastLocateRows(trimmed); ok && spacefastDecode(rowsRaw, &rows) == nil {
			// Columns in the order the command emitted them (Go maps drop it).
			order = spacefastRowKeyOrder(rowsRaw)
		} else {
			rows = nil
		}
	}

	var content strings.Builder
	if len(rows) > 0 {
		var cols []string
		seen := map[string]bool{}
		for _, r := range rows {
			keys := make([]string, 0, len(r))
			for k := range r {
				keys = append(keys, k)
			}
			sort.SliceStable(keys, func(i, j int) bool {
				oi, iok := order[keys[i]]
				oj, jok := order[keys[j]]
				if iok != jok {
					return iok
				}
				if oi != oj {
					return oi < oj
				}
				return keys[i] < keys[j]
			})
			for _, k := range keys {
				if !seen[k] && len(cols) < spacefastMaxTableCols {
					seen[k] = true
					cols = append(cols, k)
				}
			}
		}
		shown := rows
		if len(shown) > spacefastMaxTableRows {
			shown = shown[:spacefastMaxTableRows]
		}
		fmt.Fprintf(&content, "<p class=\"meta\">%d rows", len(rows))
		if len(shown) < len(rows) {
			fmt.Fprintf(&content, " (first %d shown)", len(shown))
		}
		content.WriteString(" · <a href=\"data.json\">data.json</a></p>\n<div class=\"wrap\"><table>\n<thead><tr>")
		for _, c := range cols {
			fmt.Fprintf(&content, "<th>%s</th>", html.EscapeString(c))
		}
		content.WriteString("</tr></thead>\n<tbody>\n")
		for _, r := range shown {
			content.WriteString("<tr>")
			for _, c := range cols {
				cell := spacefastCell(r[c])
				if strings.HasPrefix(cell, "https://") && !strings.ContainsAny(cell, " \"<>") {
					fmt.Fprintf(&content, "<td><a href=\"%s\">%s</a></td>", html.EscapeString(cell), html.EscapeString(cell))
				} else {
					fmt.Fprintf(&content, "<td>%s</td>", html.EscapeString(cell))
				}
			}
			content.WriteString("</tr>\n")
		}
		content.WriteString("</tbody></table></div>\n")
	} else {
		text := string(body)
		if isJSON {
			if pretty, err := json.MarshalIndent(parsed, "", "  "); err == nil {
				text = string(pretty)
			}
		}
		fmt.Fprintf(&content, "<pre>%s</pre>\n", html.EscapeString(text))
	}

	title := html.EscapeString(spacefastTitle(name))
	stamp := time.Now().UTC().Format("Jan 2, 2006 15:04 UTC")
	var page strings.Builder
	page.WriteString("<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">\n")
	page.WriteString("<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n")
	fmt.Fprintf(&page, "<title>%s</title>\n", title)
	page.WriteString(`<style>
:root{--bg:#fbfaf7;--fg:#1d1d1b;--muted:#6b6a65;--line:#e4e1d9;--head:#f1eee6;--accent:#2f5d50}
@media (prefers-color-scheme:dark){:root{--bg:#141413;--fg:#ecebe6;--muted:#9a988f;--line:#2c2b28;--head:#1e1d1b;--accent:#8cc5b3}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.5 ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}
main{max-width:1200px;margin:0 auto;padding:32px 16px 48px}h1{font-size:26px;margin:0 0 4px;letter-spacing:-.01em}
.meta{color:var(--muted);font-size:13px;margin:0 0 20px}a{color:var(--accent)}
.wrap{overflow-x:auto;border:1px solid var(--line);border-radius:10px}
table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}
th,td{padding:8px 12px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top;white-space:nowrap;max-width:420px;overflow:hidden;text-overflow:ellipsis}
th{background:var(--head);font-weight:600;font-size:13px;position:sticky;top:0}tbody tr:last-child td{border-bottom:0}
pre{background:var(--head);border:1px solid var(--line);border-radius:10px;padding:16px;overflow-x:auto;font-size:13px}
footer{color:var(--muted);font-size:12px;margin-top:28px}
</style></head><body><main>
`)
	fmt.Fprintf(&page, "<h1>%s</h1>\n<p class=\"meta\">From <code>printing-press-golden-pp-cli</code> · %s</p>\n", title, stamp)
	page.WriteString(content.String())
	page.WriteString("<footer>Printed by the CLI Printing Press · hosted on Spacefast</footer>\n</main></body></html>\n")
	return []byte(page.String())
}
